const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const [rows, cols] = lines[0].trim().split(/\s+/).map(Number);
const points = lines.slice(1, rows + 1).map((line) => line.trim().split(/\s+/).map(Number));

const dp = Array.from({ length: rows }, () => new Array(cols).fill(0));
for (let r = 0; r < rows; r++) {
  for (let c = 0; c < cols; c++) {
    if (r === 0 && c === 0) {
      dp[r][c] = points[r][c];
    } else {
      const up = r > 0 ? dp[r - 1][c] : -Infinity;
      const left = c > 0 ? dp[r][c - 1] : -Infinity;
      dp[r][c] = points[r][c] + Math.max(up, left);
    }
  }
}

for (const row of dp) {
  console.log(row.join(" "));
}
console.log(`most: ${dp[rows - 1][cols - 1]}`);
